import{_ as s,o as d,c as e,ag as a}from"./chunks/framework.C9sp7nFj.js";const i="/images/movj-examples.png",k=JSON.parse('{"title":"MovJ 关节进行点到点","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJ.md","filePath":"3. 指令/1. 运动指令/MovJ.md","lastUpdated":1778862643000}'),o={name:"3. 指令/1. 运动指令/MovJ.md"};function n(r,t,p,l,h,c){return d(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="movj-关节进行点到点" tabindex="-1">MovJ 关节进行点到点 <a class="header-anchor" href="#movj-关节进行点到点" aria-label="Permalink to &quot;MovJ 关节进行点到点&quot;">​</a></h1><p>该指令表示机器人各个关节进行点到点的运动（point to point），机器人的末端轨迹为不规则的曲线，并且在该指令运行结束时可进行 IO 指令的操作。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJ(P, [V], [B], [C], [Tool], [Coord], [PayLoad], [O], [CTV], [DO])</p><p>MovJ(目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], [姿态控制], [连续轨迹速度], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>坐标系下的目标点位置。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>用于指定机器人执行 MovJ 时的速度，包括机器人末端的平移速度、旋转速度以及外部轴的移动速度等。SPEED 变量中的 <code>per</code> 分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式：<br><code>FINE</code>：无过渡。<br><code>RELATIVE</code>：相对过渡。<br><code>ABSOLUTE</code>：绝对过渡。<br><code>DEFAULT</code>：缺省类型。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量</td><td>机器人执行该轨迹时使用的用户坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：本段轨迹受全局速度倍率影响。<br><code>GOVROFF</code>：本段轨迹不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[CTV]</td><td>CTV 变量</td><td>机器人无限旋转轴与无限旋转速度。</td><td>可选，默认不开启无限旋转</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后，可触发的 IO 操作：<br><code>NULL</code>：无任何操作。<br><code>IO 指令</code>：执行 IO 操作，目前支持的 IO 指令有 <code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><p><code>MovJ (P1, V50, &quot;RELATIVE&quot;, C100)</code></p><p>机器人以 V50 的速度运行到 P1 点，并与下一轨迹存在过渡，过渡值为 C100。</p><p><strong>示例 2：</strong></p><p><code>MovJ (P2, V50, &quot;RELATIVE&quot;, C0) Do SetDO(DO0,0)</code></p><p>机器人以 V50 的速度运行到 P2 点，且无过渡，运行至 P2 点时，设置 DO0 变量对应 IO 端口为 0。</p><p><strong>示例 3：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">nullTool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">World</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P2, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, Tool1, UserCoord1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>机器人以 50 的速度运动到 P1 点，其后由于 P2 点坐标系与 P1 点不一致，故在运动到 P2 前会先自动将工具参数切换成 Tool1，用户坐标系切换成 UserCoord1，其后运动到 P2。由于自动切换了坐标系，从 P1 运动到 P2 的过程中无过渡效果。</p><p><strong>示例 4：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, Tool1, UserCoord1)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (P2, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100, Tool1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>机器人以 50 的速度运动到 P1 点，其后由于 P2 点坐标系与 P1 点一致，无需切换坐标系，机器人会以过渡的方式运行到 P2。</p><p><img src="`+i+'" alt=""></p>',24)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
